<script lang="ts">
 import {onMount} from 'svelte';import {goto} from '$app/navigation';import {page} from '$app/state';import {Button} from '$lib/components/ui/button';import {request} from '../api';import VideoPlayer from '../VideoPlayer.svelte';import VideoActions from './VideoActions.svelte';import VideoCard from './VideoCard.svelte';import AccessGate from './AccessGate.svelte';
 let {id,user}:{id:string;user:any}=$props();let video=$state<any>(null),actions=$state<any>(null),related=$state<any[]>([]),prefs=$state<any>({autoplay_next:false}),error=$state(''),playingError=$state(''),retry=$state(0),followed=$state(false),busy=$state(false),nextVideo=$state(false),countdown=$state(5);let alive=true;
 $effect(()=>{if(!nextVideo||!prefs.autoplay_next||!related.length)return;countdown=5;const timer=setInterval(()=>{countdown--;if(countdown<=0){clearInterval(timer);void goto(`/watch/${related[0].id}?autoplay=1`);}},1000);return()=>clearInterval(timer);});
 onMount(()=>{void load();return()=>{alive=false;};});async function load(){error='';try{const [v,a,list,p]=await Promise.all([request(`/videos/${id}`),request(`/videos/${id}/actions`),request(`/videos/${id}/related`).catch(()=>[]),user?request('/settings/preferences').catch(()=>({})):Promise.resolve({})]);if(!alive)return;video=v;actions=a;related=list;prefs=p;try{const channel=await request(`/channels/${v.handle}`);if(alive)followed=channel.is_following===true;}catch{}}catch(e){if(alive)error=(e as Error).message;}}
 async function follow(){if(!user){await goto(`/login?returnTo=%2Fwatch%2F${id}`);return;}busy=true;try{await request(`/channels/${video.channel_id}/follow`,{},followed?'DELETE':'POST');followed=!followed;}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
{#if error}<div class="cloud-empty"><h1>We couldn't open this video</h1><p>{error}</p><Button variant="outline" onclick={load}>Try again</Button><Button variant="ghost" href="/discover">Browse videos</Button></div>{:else if video&&actions}<div class="watch-page"><div class="watch-primary">
{#if actions.access==='allowed'}<div class="watch-screen">{#if playingError}<div class="playback-error"><p>{playingError}</p><Button variant="outline" onclick={()=>{playingError='';retry++;}}>Retry playback</Button></div>{:else}{#key id+':'+retry}<VideoPlayer videoId={id} signedIn={!!user} resumeAt={actions.position_ms||0} captions={prefs.captions_enabled} dataSaving={prefs.data_saving} autoplay={page.url.searchParams.get('autoplay')==='1'&&prefs.autoplay_next} onended={()=>{if(prefs.autoplay_next&&related.length)nextVideo=true;}} onerror={message=>playingError=message}/>{/key}{/if}</div>{:else}<AccessGate access={actions.access} returnTo={`/watch/${id}`}/>{/if}
<h1>{video.title}</h1><div class="watch-meta"><span>{video.views.toLocaleString()} views</span><span>{new Date(video.created_at).toLocaleDateString()}</span>{#if video.ai_generated}<span>AI-generated</span>{/if}{#if video.format==='short'}<a href={`/shorts/${id}`}>Watch as Short</a>{/if}</div>
<div class="watch-creator-actions"><div class="watch-creator"><a href={`/channels/${video.handle}`}><span class="creator-initial">{(video.channel_name||video.handle||'V')[0].toUpperCase()}</span><strong>{video.channel_name||video.handle}</strong></a>{#if user?.channel_id!==video.channel_id}<Button variant="outline" size="sm" disabled={busy} onclick={follow}>{followed?'Following':'Follow'}</Button>{/if}</div><VideoActions {video} {user}/></div>
{#if nextVideo}<div class="watch-next" role="status"><p>Up next: {related[0].title} <span aria-hidden="true"> · {countdown}s</span></p><Button href={`/watch/${related[0].id}`}>Play next</Button><Button variant="ghost" onclick={()=>nextVideo=false}>Stay here</Button></div>{/if}
<details class="watch-description"><summary>About this video</summary><p>{video.description||'The creator has not added a description.'}</p></details></div>
<aside class="watch-related"><h2>More to watch</h2>{#each related as item(item.id)}<VideoCard video={item}/>{:else}<p class="subtle">More public videos will appear here.</p><Button variant="ghost" href="/discover">Explore Discover</Button>{/each}</aside></div>{:else}<div class="watch-skeleton" role="status" aria-label="Loading video"><div></div><span></span></div>{/if}
<style>.watch-page{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:30px}.watch-primary{min-width:0}.watch-screen{aspect-ratio:16/9;background:#000;display:flex;align-items:center;justify-content:center;border-radius:12px;overflow:hidden}.watch-screen :global(video){width:100%;height:100%;object-fit:contain}.watch-primary h1{font-size:23px;font-weight:600;line-height:1.4;letter-spacing:-.02em;margin:20px 0 9px}.watch-meta{display:flex;gap:15px;flex-wrap:wrap;color:var(--muted-foreground);font-size:12px}.watch-meta a{text-decoration:underline;text-underline-offset:4px}.watch-creator-actions{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:20px;padding:23px 0;border-bottom:1px solid var(--border)}.watch-creator{display:flex;gap:18px;align-items:center}.watch-creator>a{display:flex;gap:10px;align-items:center;font-size:13px}.creator-initial{display:flex;align-items:center;justify-content:center;border-radius:50%;background:var(--muted);width:34px;height:34px}.watch-description{padding:23px 0;font-size:13px}.watch-description summary{cursor:pointer;font-weight:550}.watch-description p{line-height:1.9;white-space:pre-wrap;color:var(--muted-foreground);margin-top:14px;max-width:70ch}.watch-related{display:grid;gap:22px;align-content:start}.watch-related h2{font-size:15px;font-weight:600}.playback-error{display:grid;gap:20px;text-align:center;padding:25px;font-size:13px;color:white}.watch-next{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:20px;font-size:13px}.watch-skeleton>div{aspect-ratio:16/9;max-width:900px;background:var(--muted);border-radius:12px}.watch-skeleton span{display:block;margin-top:24px;width:40%;height:20px;background:var(--muted);border-radius:4px}@media(max-width:1000px){.watch-page{grid-template-columns:minmax(0,1fr)}.watch-related{grid-template-columns:repeat(2,minmax(0,1fr));margin-top:20px}.watch-related h2{grid-column:1/-1}}@media(max-width:600px){.watch-primary h1{font-size:20px}.watch-related{grid-template-columns:1fr}.watch-creator-actions{gap:18px}.watch-screen{border-radius:8px}}
</style>
